<?php
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../includes/database.php';require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/exam_paper_page.php';
require_once __DIR__.'/../../includes/exam_question_language.php';
Auth::requireRole(['super_admin','school_admin','teacher']);Auth::requireAccess('exam_paper_generator');
$db=getDB();$actor=learningActor($db,(int)Auth::getUserId(),(int)Auth::getSchoolId(),Auth::isReadOnly());$class=(int)($_POST['class_id']??$_GET['class_id']??0);$subject=(int)($_POST['subject_id']??$_GET['subject_id']??0);$initialConfig=[];$error='';$paper=null;$title=is_string($_POST['exam_title']??null)?$_POST['exam_title']:'Examination';$selectedExam=null;
$generationMode=$_POST['generation_mode']??$_GET['generation_mode']??(isset($_POST['config_json'])?'advanced':'chapter');
$generationKind=$_POST['generation_kind']??$_GET['generation_kind']??'written';
try{$questionLanguage=examQuestionLanguage($_POST['language']??$_GET['language']??'both');}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),422);}
if(!is_string($generationMode)||!in_array($generationMode,['chapter','advanced'],true)||!is_string($generationKind)||!in_array($generationKind,['written','mcq'],true))denySchoolRequest('Choose a valid paper generation mode.',422);
if($_SERVER['REQUEST_METHOD']==='GET'&&isset($_GET['grid_id'])){try{$g=examGridRecord($db,$actor,learningId($_GET['grid_id']));$class=$g['local_class_id'];$subject=$g['local_subject_id'];$initialConfig=examGridInputJson($g['config_json']);$generationMode='advanced';}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}}
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{if(($_POST['action']??'')!=='generate')throw new InvalidArgumentException('Choose one paper generation action.');if(!is_string($_POST['exam_title']??null)||trim($title)===''||mb_strlen($title)>200)throw new InvalidArgumentException('Enter an exam title of at most 200 characters.');
        if(!empty($_POST['exam_id'])){$selectedExam=schoolRecord($db,'exams',learningId($_POST['exam_id']),$actor['school_id']);$q=$db->prepare('SELECT id FROM exam_subjects WHERE exam_id=? AND class_id=? AND subject_id=?');$q->execute([$selectedExam['id'],$class,$subject]);if(!$q->fetchColumn())throw new InvalidArgumentException('Map this class subject to the selected exam first, or choose a standalone paper.');$title=$selectedExam['name'];}
        if($generationMode==='chapter')$paper=examGenerateChapterPaper($db,$actor,$class,$subject,$_POST);
        else{$initialConfig=examGridInputJson($_POST['config_json']??null);$paper=examGeneratePaper($db,$actor,$class,$subject,$initialConfig);}
        learningAudit($db,$actor,'Generate exam paper','exam_paper_grids',0);
    }catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();}catch(Throwable $e){http_response_code(500);$error=schoolPublicError($e);}
}
[$classes,$subjectsByClass]=examPageSelectors($db,$actor);try{[$chapters,$topicsByChapter,$savedGrids,$referenceGrids]=examPageCatalog($db,$actor,$class,$subject);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
$q=$db->prepare('SELECT * FROM schools WHERE id=?');$q->execute([$actor['school_id']]);$school=$q->fetch(PDO::FETCH_ASSOC)?:[];
$q=$db->prepare('SELECT id,name FROM exams WHERE school_id=? ORDER BY id DESC');$q->execute([$actor['school_id']]);$exams=$q->fetchAll(PDO::FETCH_ASSOC);
$className='';foreach($classes as $c)if((int)$c['id']===$class)$className=$c['name'];$subjectName='';foreach($subjectsByClass[$class]??[] as $s)if((int)$s['id']===$subject)$subjectName=$s['name_en'];
$pageTitle='Exam Paper Generator';$activePage='exam_paper_generator';$pageStyles=[];
foreach(['exam-paper.css','exam-question-language.css'] as $style)$pageStyles[]='/assets/css/'.$style.'?v='.(int)filemtime(__DIR__.'/../../assets/css/'.$style);
ob_start(); ?>
