<nav class="nav nav-pills gap-2 mb-3" aria-label="Paper generation mode"><?php foreach(['chapter'=>'By chapter (simple)','advanced'=>'Advanced grid'] as $mode=>$label): ?><a class="nav-link <?= $generationMode===$mode?'active':'' ?>" <?= $generationMode===$mode?'aria-current="page"':'' ?> href="<?= APP_URL ?>/modules/learning/exam_paper_generator.php?<?= http_build_query(['class_id'=>$class,'subject_id'=>$subject,'generation_mode'=>$mode,'generation_kind'=>$generationKind,'language'=>$questionLanguage]) ?>"><?= $label ?></a><?php endforeach; ?></nav>
<div class="mb-3"><label for="examPaperLanguage" class="form-label">Question / print language</label><select id="examPaperLanguage" name="language" form="examPaperForm" class="form-select w-auto" data-exam-language-control><?php foreach(examQuestionLanguages() as $key=>$label): ?><option value="<?= $key ?>" <?= $questionLanguage===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><div class="form-text">Both languages is the default. You can change the preview and print language after generation without selecting different questions.</div></div>
<?php if($subject): ?><form method="post" id="examPaperForm"><input type="hidden" name="action" value="generate"><input type="hidden" name="generation_mode" value="<?= $generationMode ?>"><input type="hidden" name="class_id" value="<?= $class ?>"><input type="hidden" name="subject_id" value="<?= $subject ?>"><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Paper title</label><input class="form-control" name="exam_title" maxlength="200" required value="<?= sanitize($title) ?>"></div><div class="col-md-6"><label class="form-label">Link existing exam (optional)</label><select class="form-select" name="exam_id"><option value="">Standalone exam paper</option><?php foreach($exams as $e): ?><option value="<?= $e['id'] ?>" <?= (int)($_POST['exam_id']??0)===(int)$e['id']?'selected':'' ?>><?= sanitize($e['name']) ?></option><?php endforeach; ?></select></div></div><?php include __DIR__.'/../../includes/'.($generationMode==='chapter'?'exam_chapter_editor.php':'exam_grid_editor.php'); ?><button class="btn btn-success mb-4" <?= $generationMode==='chapter'&&!$chapters?'disabled':'' ?>>Generate complete Exam Paper</button></form><?php else: ?><p class="alert alert-info">Choose a class and subject to load its chapters.</p><?php endif; ?>
</div>
<?php if($paper): $mcqs=array_values(array_filter($paper['questions'],static fn($q)=>$q['type']==='MCQ'));$serial=$mcqs?2:1; ?>
<div class="alert alert-success no-print" role="status">Exam paper generated successfully: <?= count($paper['questions']) ?> question items, <?= learningDecimalString($paper['total_units']) ?> marks. Required question time: <?= learningDecimalString($paper['required_units']) ?> minutes.</div>
<div class="no-print d-flex flex-wrap align-items-center gap-2 mb-3"><label for="examPrintLanguage">Print language</label><select id="examPrintLanguage" class="form-select w-auto" data-exam-language-control><?php foreach(examQuestionLanguages() as $key=>$label): ?><option value="<?= $key ?>" <?= $questionLanguage===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="button" class="btn btn-primary" data-exam-print="questions">Print Exam Paper</button><button type="button" class="btn btn-outline-primary" data-exam-print="answers">Print Answer Key</button></div>
