<?php if(!empty($school['logo'])): ?><img class="exam-print-logo" src="<?= sanitize(APP_URL.'/uploads/logo/'.rawurlencode(basename($school['logo']))) ?>" alt="School logo"><?php endif; ?>
<div><h2><?= sanitize($school['name_en']??'School Examination') ?></h2><p><?= sanitize($school['address']??'') ?></p><h3><?= sanitize($title) ?></h3></div></header>
<div class="exam-print-metadata"><span><?= sanitize($className) ?> — <?= sanitize($subjectName) ?></span><span>Full marks: <?= learningDecimalString($paper['total_units']) ?></span><span>Time: <?= sanitize($paper['grid']['duration_minutes']) ?> minutes</span><?php if($selectedExam): ?><span>Exam date: <?= sanitize(schoolDateLabel($selectedExam['start_date'],'BS','ymd')) ?></span><?php endif; ?></div><p class="exam-instructions">Attempt all questions. Figures in the margin indicate full marks.</p>
<?php if($mcqs): ?><h4 class="exam-section-title">1. Multiple-choice questions <span>[<?= learningDecimalString(array_sum(array_column($mcqs,'marks_units'))) ?>]</span></h4><?php foreach($mcqs as $i=>$q): ?><div class="exam-question"><div class="exam-question-heading"><strong>(<?= $i+1 ?>)</strong><div><?= examQuestionRichVariants($q['question_text'],$q['question_text_np']??'',$questionLanguage,true) ?></div><span>[<?= learningDecimalString($q['marks_units']) ?>]</span></div><div class="exam-mcq-options"><?php $en=json_decode($q['options'],true);$np=json_decode($q['options_np'],true);foreach(['A','B','C','D'] as $o): ?><div><strong><?= strtolower($o) ?>.</strong> <?= examQuestionRichVariants($en[$o]??'',$np[$o]??'',$questionLanguage) ?></div><?php endforeach; ?></div></div><?php endforeach; endif; ?>
<?php foreach($paper['rows'] as $r): if($r['type']==='MCQ')continue; ?><h4 class="exam-section-title"><?= sanitize($r['name']) ?> <span>[<?= sanitize($r['total_marks']) ?>]</span></h4><?php foreach($r['questions'] as $q): ?><div class="exam-question"><div class="exam-question-heading"><strong><?= $serial++ ?>.</strong><div><?= examQuestionRichVariants($q['question_text'],$q['question_text_np']??'',$questionLanguage,true) ?></div><span>[<?= learningDecimalString($q['marks_units']) ?>]</span></div></div><?php endforeach; endforeach; ?>
</section>
<section id="examAnswersSheet" class="exam-paper card card-body mb-4"><h2>Answer Key — <?= sanitize($title) ?></h2><p><?= sanitize($className.' — '.$subjectName) ?></p><?php if($mcqs): ?><h3>1. MCQ answers</h3><ol><?php foreach($mcqs as $q): ?><li><strong><?= sanitize($q['correct_option']) ?></strong> <?= examQuestionRichVariants($q['answer']??'',$q['answer_np']??'',$questionLanguage) ?></li><?php endforeach; ?></ol><?php endif; ?><?php $serial=$mcqs?2:1;foreach($paper['rows'] as $r): if($r['type']==='MCQ')continue;foreach($r['questions'] as $q): ?><article class="exam-question"><h3><?= $serial++ ?>. [<?= learningDecimalString($q['marks_units']) ?>]</h3><?php if(!questionImportHasContent($q['answer']??'')&&!questionImportHasContent($q['answer_np']??'')): ?><p class="text-muted">No model answer supplied; prepare the marking guide before assessment.</p><?php else: ?><?= examQuestionRichVariants($q['answer']??'',$q['answer_np']??'',$questionLanguage) ?><?php endif; ?></article><?php endforeach;endforeach; ?></section>
